        // engine's JavaScript session with every handle (3/3, 2026-10-07). Handle every action's
        // promise here, still returning it, so an await sees the error and nothing is unhandled.
        return (...args) => {
          const pending = act(...args);
          pending.catch(error => state.failures.push(name + ': ' + (error?.message ?? error)));
          return pending;
        };
      } });
      state.proxies.add(proxy); state.wrapped.set(target, proxy); state.raws.set(proxy, target);
      return proxy;
    };
    cua.getApp = async (...args) => { checkNative(); return state.activeApp = wrap(await state.getApp(...args)); };
    state.wrap = wrap;
  };
{
  if (typeof globalThis.__sleightDocumentGuardSetup !== 'function') {
    throw new Error('Sleight guard setup is missing. Send a standalone app acquisition before acting.');
  }
  globalThis.__sleightDocumentGuardSetup(undefined);

  nodeRepl.write("[sleight:guard-ready]\n");
}
